WITH RECURSIVE sub AS (
    SELECT id FROM device_group
    WHERE id = #{rootId}
      AND user_id = #{userId}
      AND deleted = 0
    UNION ALL
    SELECT g.id FROM device_group g
    JOIN sub ON g.parent_id = sub.id
    WHERE g.user_id = #{userId}
      AND g.deleted = 0
)
SELECT id FROM sub

SELECT COUNT(*)
FROM device_group
WHERE user_id = #{userId}
  AND deleted = 0
  AND name = #{name}


        AND parent_id = #{parentId}


        AND parent_id IS NULL



    AND id != #{excludeId}

SELECT MAX(sort_order)
FROM device_group
WHERE user_id = #{userId}
  AND deleted = 0


        AND parent_id = #{parentId}


        AND parent_id IS NULL
